        var sort=new ComboBox{MinWidth=135,Margin=new(10,0,0,0),VerticalContentAlignment=VerticalAlignment.Center};foreach(var pair in new[]{("Recent",T("Recent","الأحدث")),("Name",T("Name","الاسم")),("Size",T("Size","الحجم"))}){var option=new ComboBoxItem{Content=pair.Item2,Tag=pair.Item1};sort.Items.Add(option);if(pair.Item1==downloadLibrarySort)sort.SelectedItem=option;}DownloadName(sort,T("Sort local files","ترتيب الملفات المحلية"));sort.SelectionChanged+=(_,_)=>{downloadLibrarySort=(string)((ComboBoxItem)sort.SelectedItem).Tag;_=BuildDownloadLibrary(host);};filters.Children.Add(sort);
