        try{
            var groups=await Task.Run(()=>manager.LocalLibrary(filter,order));if(!host.Children.Contains(rows))return;rows.Children.Clear();
            if(groups.Count==0){rows.Children.Add(Body(T("No matching videos on this PC.","لا توجد فيديوهات مطابقة على هذا الكمبيوتر.")));return;}
            int shown=0;
            void More(){var batch=groups.Skip(shown).Take(60).ToList();shown+=batch.Count;foreach(var group in batch)rows.Children.Add(LocalGroup(group));if(shown<groups.Count){var more=ManageButton(T("Show more","عرض المزيد"),()=>{rows.Children.RemoveAt(rows.Children.Count-1);More();});rows.Children.Add(more);}}
            FrameworkElement LocalGroup(DownloadLocalGroup group)
            {
                var all=group.Files;var body=new StackPanel();var header=LocalRow(group.Key=="movies"?T("Movies","الأفلام"):group.Name,all,null);var expander=new Expander{Header=header,Content=body,Margin=new(0,0,0,10),HorizontalContentAlignment=HorizontalAlignment.Stretch,Tag="DownloadLibraryGroup:"+group.Key};DownloadName(expander,group.Name);bool built=false;
                void Fill(){if(built)return;built=true;if(group.Key=="movies")AddFiles(body,all);else foreach(var season in all.GroupBy(f=>f.Item.Season).OrderBy(g=>g.Key)){var key=group.Key+":"+season.Key;var seasonBody=new StackPanel{Margin=new(16,0,0,0)};var seasonFiles=season.ToList();var seasonView=new Expander{Header=LocalRow(T("Season {0}","الموسم {0}",season.Key),seasonFiles,null),Content=seasonBody,Margin=new(12,0,0,8),HorizontalContentAlignment=HorizontalAlignment.Stretch};DownloadName(seasonView,T("Season {0}","الموسم {0}",season.Key));bool populated=false;seasonView.Expanded+=(_,e)=>{e.Handled=true;downloadLibraryExpanded.Add(key);if(!populated){populated=true;AddFiles(seasonBody,seasonFiles);}};seasonView.Collapsed+=(_,e)=>{e.Handled=true;downloadLibraryExpanded.Remove(key);};body.Children.Add(seasonView);seasonView.IsExpanded=downloadLibraryExpanded.Contains(key);}}
                expander.Expanded+=(_,e)=>{e.Handled=true;downloadLibraryExpanded.Add(group.Key);Fill();};expander.Collapsed+=(_,e)=>{e.Handled=true;downloadLibraryExpanded.Remove(group.Key);};expander.IsExpanded=downloadLibraryExpanded.Contains(group.Key);return expander;
            }
            void AddFiles(StackPanel parent,List<DownloadLocalFile> files)
            {
                var sorted=order=="Size"?files.OrderByDescending(f=>f.Bytes):order=="Recent"?files.OrderByDescending(f=>f.Modified):files.OrderBy(f=>f.Item.Label,StringComparer.CurrentCultureIgnoreCase);var list=sorted.ToList();int count=0;
                void Next(){foreach(var file in list.Skip(count).Take(60))parent.Children.Add(LocalRow(file.Item.IsMovie?file.Item.Title:file.Item.EpisodeLabel+(file.Item.EpisodeTitle.Length>0?" · "+file.Item.EpisodeTitle:""),[file],file));count+=60;if(count<list.Count)parent.Children.Add(ManageButton(T("Show more","عرض المزيد"),()=>{parent.Children.RemoveAt(parent.Children.Count-1);Next();}));}Next();
            }
