                var tools=new StackPanel{Orientation=Orientation.Horizontal,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(tools,1);row.Children.Add(tools);var trash=ManageButton("",()=>ShowDownloadDelete(title,files));trash.FontFamily=new System.Windows.Media.FontFamily("Segoe Fluent Icons, Segoe MDL2 Assets");trash.ToolTip=T("Delete files","حذف الملفات");trash.Margin=new(4,0,4,0);DownloadName(trash,T("Delete files for","حذف ملفات")+" "+title);tools.Children.Add(trash);var more=ManageButton("[[more]]",()=>{});more.Margin=new(4,0,4,0);DownloadName(more,T("More options for","خيارات أخرى لـ")+" "+title);tools.Children.Add(more);
                more.Click+=(_,e)=>{e.Handled=true;var menu=new ContextMenu{FlowDirection=FlowDirection};void Entry(string label,Action action){var entry=new MenuItem{Header=label};DownloadName(entry,label);entry.Click+=(_,_)=>action();menu.Items.Add(entry);}if(file!=null)Entry(T("Play","تشغيل"),()=>{var item=store.Archive.FirstOrDefault(i=>i.Id==file.Item.Id);if(item!=null)_=PlayVideo(item);});Entry(T("Show in folder","إظهار في المجلد"),()=>ShowInFolder(files[0].Path));Entry(T("Delete","حذف")+" "+Videos(files.Count)+"…",()=>ShowDownloadDelete(title,files));if(file==null)Entry(T("Delete watched…","حذف المشاهد…"),()=>ShowDownloadDelete(title,files.Where(f=>f.Watched).ToList(),true));Entry(T("Move to…","نقل إلى…"),()=>ShowDownloadMove(title,files));more.ContextMenu=menu;menu.PlacementTarget=more;menu.IsOpen=true;};return new Border{Background=Brush("#141416"),CornerRadius=new(10),BorderThickness=new(1),BorderBrush=Brush("#26FFFFFF"),Child=row,Margin=new(0,0,0,5),Tag="DownloadLocalRow"};
            }
            More();
        }catch(Exception e){loading.Text=T("Couldn't read local files: ","تعذرت قراءة الملفات المحلية: ")+e.Message;}
