        var remember=new CheckBox{Content=T("Remember my choice","تذكر اختياري"),Margin=new(0,18,0,12)};DownloadName(remember,(string)remember.Content);sheet.Add(remember);var note=Body("",12);sheet.Add(note);sheet.Action(T("Cancel","إلغاء"),()=>sheet.Close(false));
        var submit=sheet.Action(T("Delete","حذف")+" "+Videos(files.Count),()=>{},true);submit.IsEnabled=files.Count>0;submit.Click+=async(_,_)=>{var choice=recycle.IsChecked==true?DownloadDeleteChoice.Recycle:DownloadDeleteChoice.Permanent;var save=remember.IsChecked==true;submit.IsEnabled=false;sheet.CanClose=()=>false;try{if(save)downloads.SetDeleteChoice(choice);var result=await Task.Run(()=>downloads.DeleteLocal(files,choice,watchedOnly));if(result.Errors.Count>0){note.Text=ManageResult(result);submit.IsEnabled=true;}else{sheet.Close(true);Status.Text=ManageResult(result);RefreshDownloadLibrary();}}catch(Exception e){note.Text=e.Message;submit.IsEnabled=true;}finally{sheet.CanClose=null;}};
